insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0004-0000-4000-8000-000000000036', 'en', null, 'Biology', 'Biology is the scientific study of life and living organisms, reaching from molecules and single cells all the way up to whole ecosystems. This foundations course walks through cells, energy, genetics, evolution, classification, ecology, and the human body, one clear idea at a time. Structure and topics are adapted from the Biology overview on Wikipedia, the free encyclopedia (CC BY-SA 4.0).', null, 'foundations', 52, true, 'science', '{}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0004-0000-4000-8000-000000000036', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"Which of these is a shared characteristic of all living things?","options":["They are all able to fly","They all carry out metabolism and respond to their surroundings","They are all made of metal","They never change over time"],"answer":1,"explanation":"Living things share features such as cells, metabolism, growth, response to stimuli, and reproduction - see ''What biology studies and the characteristics of life''."},{"prompt":"The cell theory states that...","options":["only animals are made of cells","all living things are made of one or more cells and cells come from other cells","cells are only found in plants","cells are too small to study"],"answer":1,"explanation":"The cell theory says cells are the basic unit of life and arise from pre-existing cells."},{"prompt":"A key difference between a prokaryotic and a eukaryotic cell is that...","options":["prokaryotes are larger","eukaryotes have a true nucleus and membrane-bound organelles","prokaryotes have more organelles","only prokaryotes contain DNA"],"answer":1,"explanation":"Eukaryotic cells keep their DNA in a membrane-bound nucleus; prokaryotic cells do not."},{"prompt":"Proteins are built from which smaller building blocks?","options":["sugars","fatty acids","amino acids","nucleotides"],"answer":2,"explanation":"A protein is a chain of amino acids folded into a working shape."},{"prompt":"Photosynthesis in plants mainly converts light energy into...","options":["heat only","chemical energy stored in sugar","sound","electricity"],"answer":1,"explanation":"Plants capture light and build sugar, storing energy in chemical bonds."},{"prompt":"In DNA, the base adenine (A) normally pairs with...","options":["guanine (G)","cytosine (C)","thymine (T)","another adenine (A)"],"answer":2,"explanation":"A pairs with T and G pairs with C, the base-pairing rule."},{"prompt":"If a tall plant with genotype Tt is crossed with another Tt, what fraction of offspring are expected to be short (tt)?","options":["none","about one quarter","about one half","all of them"],"answer":1,"explanation":"A Tt by Tt cross gives a 3 to 1 ratio, so about one quarter are tt."},{"prompt":"Natural selection means that...","options":["organisms choose their own traits","individuals better suited to their environment tend to survive and reproduce more","all individuals reproduce equally","traits never pass to offspring"],"answer":1,"explanation":"Heritable traits that aid survival and reproduction become more common over generations."}]}'::jsonb, null, 10),
  (2, 'What biology studies and the characteristics of life', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Say what biology is as a science, list the main features that living things share, and explain why biologists organize life into levels from molecules up to the whole biosphere. Warm-up from the diagnostic: name two features that a rock lacks but a mouse has."},{"heading":"The idea","text":"Biology is the scientific study of life. Because life is so varied, biologists look for the features that every living thing shares. Living organisms are made of one or more cells. They use energy and run chemical reactions, a process called metabolism. They grow and develop, respond to signals from their surroundings, and keep stable internal conditions. They reproduce, passing heritable information to offspring, and across many generations populations change, or evolve. Biologists also study life at many levels of organization. The smallest level is molecules, which build cells. Cells form tissues, tissues form organs, and organs form organ systems and whole organisms. Beyond the individual, organisms of one kind form a population, many populations form a community, a community plus its physical surroundings forms an ecosystem, and all ecosystems together form the biosphere. Looking at the right level helps a biologist ask a clear question."},{"heading":"Key methods & examples","text":"Biologists answer questions using the scientific method: they observe something, ask a question, propose a testable explanation called a hypothesis, make a prediction, and run a controlled experiment to check it. A controlled experiment changes one variable while holding the others steady, so any difference in the result can be traced to that one change. For example, to test whether light affects plant growth, a researcher grows identical seedlings and varies only the light, keeping water, soil, and temperature the same. The group kept in the dark is the control. Measurements are repeated and compared, and the explanation is kept only if the evidence supports it. Another example of levels at work: studying how a drug lowers blood sugar may begin with molecules, move to cells, and end with the whole organism. Good biology links evidence at one level to behavior at another."},{"heading":"Your turn","text":"1) List four features shared by all living things. 2) Which level of organization is just above the single cell? 3) What is the one thing a controlled experiment changes on purpose? 4) Put these in order from small to large: organ, cell, tissue, organism. 5) Why is a flame not considered alive even though it uses fuel? Answers: 1) any four of cells, metabolism, growth, response to stimuli, homeostasis, reproduction, evolution. 2) tissue. 3) a single variable, while the rest are held constant. 4) cell, tissue, organ, organism. 5) it is not made of cells and cannot reproduce or pass on heritable information."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking one feature, such as movement, defines life - a clock moves and a seed sits still, yet only the seed is alive. Mistake: calling any untested guess a hypothesis; a hypothesis must be testable and able to be shown wrong. Exit: (a) What makes an experiment controlled? (b) Name the level of organization that includes a community plus its physical surroundings. Answers: it changes only one variable while holding the rest constant; the ecosystem."}]}'::jsonb, 'Life is defined by a set of shared features working together, not by any single one - a crystal can grow, and a fire can use energy, yet neither is alive.', 12),
  (3, 'Cells and the cell theory', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"State the cell theory, tell a prokaryotic cell from a eukaryotic cell, and name the jobs of the main organelles. Warm-up: where does a eukaryotic cell keep most of its DNA?"},{"heading":"The idea","text":"The cell is the basic unit of life. The cell theory has three parts: all living things are made of one or more cells, the cell is the smallest unit that is alive, and all cells come from pre-existing cells. Cells fall into two broad types. Prokaryotic cells, such as bacteria, are small and simple; their DNA floats freely in the cytoplasm and they have no membrane-bound organelles. Eukaryotic cells, found in plants, animals, fungi, and protists, are larger and keep their DNA inside a membrane-bound nucleus. Eukaryotic cells also contain organelles, small structures that each do a job. Every cell is wrapped in a plasma membrane that controls what enters and leaves. Plant cells add a stiff cell wall and chloroplasts, while most animal cells have neither. Keeping DNA in a nucleus lets eukaryotic cells grow larger and run more complex chemistry."},{"heading":"Key methods & examples","text":"Think of the parts by their jobs. The nucleus holds the DNA and directs the cell. Mitochondria release energy from food and are often called the powerhouse of the cell. Ribosomes build proteins. The endoplasmic reticulum folds and transports those proteins, and the Golgi apparatus packages them for shipping. In plant cells, chloroplasts capture light for photosynthesis, and a large central vacuole stores water and keeps the cell firm. Scale matters: a typical bacterium is about one to two micrometers across, while an animal cell is often ten to thirty micrometers, so it has far more room inside. A worked comparison: a bacterium has no nucleus and no mitochondria, yet it still carries out metabolism; a human liver cell has a nucleus and hundreds of mitochondria because it does energy-hungry work. Studying cells relies on microscopes, since nearly all cells are too small to see with the unaided eye."},{"heading":"Your turn","text":"1) State the three parts of the cell theory. 2) Which cell type has no membrane-bound nucleus? 3) Name the organelle that releases energy from food. 4) Give two structures a plant cell has that a typical animal cell lacks. 5) What does the plasma membrane do? Answers: 1) all living things are made of cells, the cell is the basic unit of life, and cells come from existing cells. 2) prokaryotic. 3) the mitochondrion. 4) a cell wall and chloroplasts (and a large central vacuole). 5) it controls what enters and leaves the cell."},{"heading":"Common mistakes & exit ticket","text":"Mistake: saying prokaryotes have no DNA - they do, it is simply not held in a nucleus. Mistake: thinking only animal cells have mitochondria; plant cells have them too, in addition to chloroplasts. Exit: (a) Where does a eukaryotic cell store most of its DNA? (b) Which organelle builds proteins? Answers: in the nucleus; the ribosome."}]}'::jsonb, 'Prokaryotic means ''before a nucleus'' and eukaryotic means ''true nucleus'' - the words themselves tell you the main difference.', 13),
  (4, 'The molecules of life and enzymes', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Name the four main classes of biological molecules, give their building blocks and jobs, and explain how an enzyme speeds up a reaction. Warm-up: which class of molecule stores the genetic instructions?"},{"heading":"The idea","text":"Living things are built mostly from four classes of large molecules, all based on carbon. Carbohydrates are sugars and their chains; single sugars such as glucose give quick energy, and long chains such as starch store energy or, as cellulose, build plant walls. Lipids include fats and oils; they store energy densely and, as phospholipids, form the membranes that wrap every cell. Proteins are chains of amino acids folded into precise shapes. They do more jobs than any other molecule: they form structures, carry signals, move substances, and act as enzymes. Nucleic acids, namely DNA and RNA, are chains of nucleotides; DNA stores the genetic instructions and RNA helps put them to use. The key theme is that in each class, small units join into larger molecules, and the shape of the final molecule decides what it can do."},{"heading":"Key methods & examples","text":"Enzymes are proteins that speed up chemical reactions without being used up. A reaction needs a certain push to get started, called activation energy; an enzyme lowers that push, so the reaction runs far faster at normal body temperature. Each enzyme has a pocket called the active site that fits only certain molecules, its substrates, much like a lock fits a key. For example, the enzyme amylase in saliva breaks starch into smaller sugars, which is why a cracker slowly tastes sweet as you chew. Enzymes are sensitive to conditions: too much heat or the wrong acidity can change the active site shape so it no longer works, a change called denaturing. A worked case: at body temperature an enzyme may convert thousands of substrate molecules per second, but boiling it destroys that shape and stops the reaction. This is why organisms keep steady internal conditions."},{"heading":"Your turn","text":"1) Name the four main classes of biological molecules. 2) What are the building blocks of proteins? 3) Which molecule stores genetic instructions? 4) What does an enzyme do to the activation energy of a reaction? 5) Why does boiling an enzyme stop it from working? Answers: 1) carbohydrates, lipids, proteins, and nucleic acids. 2) amino acids. 3) DNA. 4) it lowers the activation energy. 5) heat changes, or denatures, the shape of the active site so the substrate no longer fits."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking an enzyme is used up in the reaction - it is released unchanged and can work again. Mistake: confusing the building blocks; proteins come from amino acids, not from sugars. Exit: (a) Which class of molecule forms cell membranes? (b) What is the name for the enzyme pocket that binds the substrate? Answers: lipids (phospholipids); the active site."}]}'::jsonb, 'The four big classes of biological molecules are built from small repeating units joined into large chains, except lipids, which are assembled a little differently.', 13),
  (5, 'Energy: photosynthesis and cellular respiration', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how photosynthesis captures light energy as sugar, how cellular respiration releases energy from sugar, and how the two processes connect. Warm-up: which gas do plants take in during photosynthesis?"},{"heading":"The idea","text":"All life needs a steady supply of usable energy. Photosynthesis is how plants, algae, and some bacteria capture energy from sunlight. Inside chloroplasts, the green pigment chlorophyll absorbs light and powers reactions that combine carbon dioxide and water into glucose, releasing oxygen as a by-product. In short: carbon dioxide plus water, driven by light, yields glucose plus oxygen. Cellular respiration runs the process the other way to release that stored energy. Inside mitochondria, glucose is broken down using oxygen, and the energy is captured in a small molecule called ATP, which cells spend to do work; carbon dioxide and water are given off. In short: glucose plus oxygen yields carbon dioxide plus water plus energy as ATP. Nearly all cells respire, including plant cells. ATP is the common energy currency: it is made during respiration and spent on everything from muscle movement to building new molecules."},{"heading":"Key methods & examples","text":"The two processes form a cycle that links the living world. Plants build sugar and release oxygen; animals and plants alike break that sugar down and release carbon dioxide, which plants then reuse. A worked example: a leaf in bright light takes in carbon dioxide and gives off oxygen, so the net flow favors photosynthesis; at night the same leaf only respires and gives off carbon dioxide. Respiration comes in two forms. Aerobic respiration uses oxygen and releases a large amount of energy. When oxygen runs short, cells switch to anaerobic respiration, or fermentation, which releases much less energy; in human muscle this produces lactic acid during hard exercise, and in yeast it produces alcohol and carbon dioxide, which is what makes bread rise. Measuring the oxygen used or the carbon dioxide released lets biologists track how fast an organism is respiring."},{"heading":"Your turn","text":"1) Write the overall word summary for photosynthesis. 2) In which organelle does photosynthesis take place? 3) What small molecule stores the energy released by respiration? 4) Name the two main types of respiration. 5) Why can a plant cell both photosynthesize and respire? Answers: 1) carbon dioxide plus water, using light, yields glucose plus oxygen. 2) the chloroplast. 3) ATP. 4) aerobic (with oxygen) and anaerobic (without oxygen). 5) it has chloroplasts for photosynthesis and mitochondria for respiration, so it does both."},{"heading":"Common mistakes & exit ticket","text":"Mistake: believing plants only photosynthesize and never respire - they respire all the time, day and night. Mistake: mixing up the inputs and outputs; respiration uses oxygen and gives off carbon dioxide, the reverse of photosynthesis. Exit: (a) What gas does photosynthesis release? (b) What does anaerobic respiration produce in human muscle? Answers: oxygen; lactic acid."}]}'::jsonb, 'Photosynthesis and respiration are near opposites: one builds sugar and stores energy, the other breaks sugar down and releases it.', 14),
  (6, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"Which statement is part of the cell theory?","options":["Cells can appear from nothing","All cells come from pre-existing cells","Only animals have cells","Cells are the largest unit of life"],"answer":1,"explanation":"The cell theory holds that cells arise only from other cells."},{"prompt":"The main difference between prokaryotic and eukaryotic cells is that eukaryotic cells have...","options":["no DNA","a membrane-bound nucleus and organelles","no membrane","a smaller size"],"answer":1,"explanation":"Eukaryotic cells keep DNA in a nucleus and contain membrane-bound organelles."},{"prompt":"Starch and cellulose are examples of which class of biological molecule?","options":["proteins","lipids","carbohydrates","nucleic acids"],"answer":2,"explanation":"Both are long chains of sugar units, so they are carbohydrates."},{"prompt":"An enzyme speeds up a reaction by...","options":["raising the activation energy","lowering the activation energy","being used up in the reaction","adding heat to the cell"],"answer":1,"explanation":"Enzymes lower the activation energy and are not consumed."},{"prompt":"In cellular respiration, glucose and oxygen are converted into carbon dioxide, water, and...","options":["chlorophyll","energy stored as ATP","starch","amino acids"],"answer":1,"explanation":"Respiration releases energy from glucose and captures it as ATP."},{"prompt":"Which organelle captures light energy during photosynthesis?","options":["the mitochondrion","the ribosome","the chloroplast","the nucleus"],"answer":2,"explanation":"Chloroplasts contain chlorophyll and carry out photosynthesis."}]}'::jsonb, null, 8),
  (7, 'DNA, genes, and cell division', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how DNA stores information, outline how a gene is used to build a protein, and tell mitosis apart from meiosis. Warm-up: which base pairs with cytosine in DNA?"},{"heading":"The idea","text":"DNA is the molecule that stores genetic instructions. It is a double helix, two strands twisted together, held by paired bases: adenine with thymine, and guanine with cytosine. The order of these bases is a code. A gene is a segment of DNA that carries the instructions for one product, usually a protein. The full set of DNA in an organism is its genome. Cells use a gene in two steps. First, in transcription, the DNA sequence of the gene is copied into a matching strand of messenger RNA. Second, in translation, ribosomes read the RNA three bases at a time; each triplet, called a codon, specifies one amino acid, and the amino acids are joined into a protein. Because base pairing is so reliable, DNA can also be copied almost exactly before a cell divides, so each new cell gets a full set of instructions."},{"heading":"Key methods & examples","text":"Cells divide in two main ways. Mitosis makes body cells for growth and repair. The DNA is copied, then split so that each of the two daughter cells receives a complete, identical set of chromosomes; the cells are genetically the same as the parent. Meiosis makes sex cells, the eggs and sperm, for reproduction. It involves two rounds of division and produces four cells, each with half the usual number of chromosomes, so that when egg and sperm join at fertilization the normal number is restored. A worked contrast: a human body cell has 46 chromosomes; mitosis yields two cells each with 46, while meiosis yields four cells each with 23. Meiosis also shuffles the genetic material, which is one reason offspring differ from their parents and from each other. This mixing is a major source of variation."},{"heading":"Your turn","text":"1) What are the two DNA base pairs? 2) What is a gene? 3) Name the two steps that turn a gene into a protein. 4) Which type of cell division produces identical body cells? 5) How many chromosomes does a human sex cell carry? Answers: 1) adenine with thymine, and guanine with cytosine. 2) a segment of DNA that codes for a product, usually a protein. 3) transcription and translation. 4) mitosis. 5) 23, half the number in a body cell."},{"heading":"Common mistakes & exit ticket","text":"Mistake: confusing mitosis and meiosis - mitosis keeps the chromosome number the same, while meiosis halves it. Mistake: thinking RNA stores the long-term instructions; DNA does, and RNA is a working copy. Exit: (a) What is a codon? (b) Why must sex cells have half the usual chromosome number? Answers: a group of three RNA bases that codes for one amino acid; so the full number is restored when egg and sperm combine at fertilization."}]}'::jsonb, 'A gene is a stretch of DNA that codes for a product; the whole set of an organism''s DNA is its genome.', 14),
  (8, 'Inheritance and evolution', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Use Mendelian rules to predict simple inheritance, read a Punnett square, and explain how natural selection drives evolution and what evidence supports it. Warm-up: if an allele is recessive, when does its trait appear?"},{"heading":"The idea","text":"Gregor Mendel worked out how traits pass from parents to offspring. Each gene can come in different versions, called alleles, and an individual carries two of each, one from each parent. A dominant allele shows its effect even if only one copy is present; a recessive trait appears only when both alleles are recessive. The combination of alleles an organism carries is its genotype, and the visible trait is its phenotype. Evolution operates on top of this inheritance. Within a population, individuals vary, and much of that variation is heritable. Natural selection is the process by which individuals whose traits suit their environment tend to survive and reproduce more, so those traits grow more common over generations. Given enough time, this can reshape a population and give rise to new species. Mutation and the shuffling of alleles supply the variation, and selection, acting on survival and reproduction, decides which variants spread."},{"heading":"Key methods & examples","text":"A Punnett square predicts the offspring of a cross. Cross two plants that are each Tt for height, where T (tall) is dominant over t (short). The square gives one TT, two Tt, and one tt, so three out of four are tall and one is short - the classic 3 to 1 ratio. The short plant appears only with two recessive alleles. For evolution, a well-known example is the peppered moth: when soot darkened tree bark, dark moths were better hidden from predators, survived more often, and became common, while pale moths declined. The evidence for evolution comes from several directions: fossils show change over long spans of time, comparing body structures reveals shared ancestry, and comparing DNA shows that closely related species have more similar sequences. Directly observed cases, such as bacteria becoming resistant to drugs, confirm that selection acts in the present."},{"heading":"Your turn","text":"1) What is an allele? 2) In a Tt by Tt cross, what fraction of offspring show the recessive trait? 3) Define phenotype. 4) State natural selection in one sentence. 5) Give two independent lines of evidence for evolution. Answers: 1) one version of a gene. 2) one quarter (the tt combination). 3) the visible trait of an organism. 4) individuals with traits that suit the environment tend to survive and reproduce more, so those traits spread. 5) any two of fossils, shared body structures, DNA comparisons, and directly observed change such as drug resistance."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking individuals evolve - populations evolve over generations, while an individual keeps the genes it was born with. Mistake: treating a dominant allele as more common or stronger; dominant only describes which allele shows when both are present. Exit: (a) What is the expected ratio of tall to short from a Tt by Tt cross? (b) Name one source of the variation that selection acts on. Answers: 3 to 1; mutation (or the shuffling of alleles during meiosis)."}]}'::jsonb, 'An allele is one version of a gene; a dominant allele shows its effect even when a recessive allele is also present.', 14),
  (9, 'The diversity of life, ecology, and the human body', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe how life is classified into domains and kingdoms, explain the basics of ecology and ecosystems, and give examples of homeostasis and the human organ systems. Warm-up: which two features define a living thing''s place in classification most narrowly?"},{"heading":"The idea","text":"Life is enormously diverse, so biologists classify organisms by shared features and shared ancestry. The broadest groups are three domains: Bacteria, Archaea, and Eukarya. Within Eukarya sit the familiar kingdoms, including animals, plants, fungi, and protists. Each organism is given a two-part scientific name from its genus and species. Ecology is the study of how organisms interact with each other and with their physical surroundings. An ecosystem is a community of living things together with the non-living environment they depend on. Energy flows through an ecosystem in food chains: producers such as plants capture energy by photosynthesis, consumers eat other organisms, and decomposers break down dead material and return nutrients to the soil. At the level of the individual, homeostasis is the keeping of stable internal conditions, such as temperature and water balance, despite changes outside. These ideas connect: a stable body supports an organism that plays a role in its ecosystem."},{"heading":"Key methods & examples","text":"A food chain shows the flow of energy: grass is eaten by a grasshopper, the grasshopper by a frog, the frog by a snake, and decomposers recycle them all. Because energy is lost at each step, chains are usually short and there are far more producers than top consumers. Homeostasis works through feedback. If your body gets too warm, you sweat and blood vessels in the skin widen to release heat; if too cold, you shiver and the vessels narrow to keep heat in. This is negative feedback, pushing conditions back toward a set point. The human body carries out such tasks through organ systems that work together: the circulatory system moves blood, the respiratory system exchanges gases, the digestive system breaks down food, the nervous system carries signals, and the skeletal and muscular systems give support and movement. No system acts alone; for example, respiration and circulation together deliver oxygen to every cell."},{"heading":"Your turn","text":"1) Name the three domains of life. 2) What is an ecosystem? 3) In a food chain, what do decomposers do? 4) Define homeostasis. 5) Name two human organ systems and one job of each. Answers: 1) Bacteria, Archaea, and Eukarya. 2) a community of organisms together with their non-living environment. 3) they break down dead material and return nutrients to the environment. 4) the keeping of stable internal conditions despite outside change. 5) for example, the circulatory system moves blood, and the respiratory system exchanges gases (other valid pairs accepted)."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking energy cycles endlessly through a food chain - energy flows one way and is lost as heat at each step, while nutrients are recycled. Mistake: treating organ systems as separate; they constantly cooperate. Exit: (a) Which domain includes animals and plants? (b) What kind of feedback returns body temperature to its set point? Answers: Eukarya; negative feedback."}]}'::jsonb, 'Classification groups organisms from broad to narrow: domain, kingdom, phylum, class, order, family, genus, species.', 14),
  (10, 'Key terms', 'vocab', '{"items":[{"term":"cell","translation":"the basic structural and functional unit of all living things","example":"A bacterium is a single cell, while a human is made of trillions of cells."},{"term":"organelle","translation":"a small structure inside a eukaryotic cell that carries out a specific job","example":"The mitochondrion is the organelle that releases energy from food."},{"term":"enzyme","translation":"a protein that speeds up a chemical reaction without being used up","example":"Amylase is an enzyme that breaks starch into smaller sugars."},{"term":"ATP","translation":"the small molecule cells use to store and spend energy, the energy currency of the cell","example":"Respiration captures energy from glucose in the form of ATP."},{"term":"gene","translation":"a segment of DNA that carries the instructions for one product, usually a protein","example":"A gene for eye color helps determine that trait."},{"term":"allele","translation":"one of the different versions a gene can take","example":"A plant may carry a tall allele and a short allele for height."},{"term":"natural selection","translation":"the process by which individuals with helpful heritable traits survive and reproduce more, spreading those traits","example":"Natural selection made dark moths common on soot-covered trees."},{"term":"homeostasis","translation":"the keeping of stable internal conditions despite changes outside the organism","example":"Sweating when hot is part of homeostasis, keeping body temperature steady."}]}'::jsonb, null, 9)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0004-0000-4000-8000-000000000036' and l.position = v.pos
);
